UPDATE PREQUL
SET    PINNUM = ''
WHERE  PINNUM = '#DOCNUM#'
       AND ITMNO = '#ITMNO#'
       AND ITMVER = '#ITMVER#'; 

DELETE FROM PINQUL
WHERE  DOCNUM + Cast(DOCLIN AS VARCHAR) = '#LINKROWID#';

DELETE FROM PINQUS
WHERE  DOCNUM + Cast(DOCLIN AS VARCHAR) = '#LINKROWID#';
